async function seed() {
  await ds.initialize();
  console.log('Connected to database');
  const qr = ds.createQueryRunner();
  await qr.connect();

  try {
    const adminRows = await qr.query('SELECT id FROM users LIMIT 1');
    const adminId: number = adminRows[0]?.id ?? 1;

    // Upsert course
    const existing = await qr.query('SELECT id FROM courses WHERE slug = ?', [COURSE_SLUG]);
    let courseId: number;
    if (existing.length > 0) {
      courseId = existing[0].id;
      await qr.query(
        `UPDATE courses SET title=?, totalLessons=?, estimatedMinutes=?, updatedAt=NOW() WHERE id=?`,
        ['Tiếng Việt lớp 3', LESSONS.length, LESSONS.length * 20, courseId],
      );
      console.log(`Updated course: Tiếng Việt lớp 3 (id=${courseId})`);
    } else {
      const res = await qr.query(
        `INSERT INTO courses
         (title, slug, shortDescription, description, courseType, difficultyLevel,
          targetAgeMin, targetAgeMax, totalLessons, estimatedMinutes,
          isPublished, isFree, price, createdById, createdAt, updatedAt)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
        [
          'Tiếng Việt lớp 3',
          COURSE_SLUG,
          'Đọc hiểu văn bản, luyện từ và câu Tiếng Việt lớp 3 - Kết nối tri thức',
          'Khóa học Tiếng Việt lớp 3 bám sát SGK Kết nối tri thức: 2 tập, 8 chủ đề, 66 bài học. Mỗi bài có bài tập Dễ, Trung bình, Khó (10 câu mỗi mức).',
          'language', 'beginner', 8, 9,
          LESSONS.length, LESSONS.length * 20,
          1, 0, 99000, adminId,
        ],
      );
      courseId = res.insertId;
      console.log(`Created course: Tiếng Việt lớp 3 (id=${courseId})`);
    }

    // ── Volumes ──
    await qr.query('DELETE FROM volumes WHERE courseId = ?', [courseId]);
    const volDefs = [
      { name: 'TIẾNG VIỆT LỚP 3 - TẬP 1', sortOrder: 1 },
      { name: 'TIẾNG VIỆT LỚP 3 - TẬP 2', sortOrder: 2 },
    ];
    const volIds: number[] = [];
    for (const v of volDefs) {
      const r = await qr.query(
        'INSERT INTO volumes (courseId, name, sortOrder, createdAt, updatedAt) VALUES (?, ?, ?, NOW(), NOW())',
        [courseId, v.name, v.sortOrder],
      );
      volIds.push(r.insertId);
    }
    const [vol1Id, vol2Id] = volIds;
    console.log(`Created volumes: ${vol1Id}, ${vol2Id}`);

    // ── Topics ──
    await qr.query('DELETE FROM topics WHERE courseId = ?', [courseId]);
    const topicDefs: { name: string; vol: number; sortOrder: number; minOrder: number; maxOrder: number }[] = [
      { name: 'Những trải nghiệm thú vị', vol: vol1Id, sortOrder: 1, minOrder: 1, maxOrder: 8 },
      { name: 'Cổng trường rộng mở', vol: vol1Id, sortOrder: 2, minOrder: 9, maxOrder: 17 },
      { name: 'Mái nhà yêu thương', vol: vol1Id, sortOrder: 3, minOrder: 18, maxOrder: 25 },
      { name: 'Cộng đồng gắn bó', vol: vol1Id, sortOrder: 4, minOrder: 26, maxOrder: 34 },
      { name: 'Những sắc màu thiên nhiên', vol: vol2Id, sortOrder: 1, minOrder: 35, maxOrder: 42 },
      { name: 'Bài học từ cuộc sống', vol: vol2Id, sortOrder: 2, minOrder: 43, maxOrder: 51 },
      { name: 'Đất nước ngàn năm', vol: vol2Id, sortOrder: 3, minOrder: 52, maxOrder: 59 },
      { name: 'Trái Đất của chúng mình', vol: vol2Id, sortOrder: 4, minOrder: 60, maxOrder: 66 },
    ];
    const topicMap: { minOrder: number; maxOrder: number; topicId: number; volId: number }[] = [];
    for (const t of topicDefs) {
      const r = await qr.query(
        'INSERT INTO topics (courseId, volumeId, name, sortOrder, createdAt, updatedAt) VALUES (?, ?, ?, ?, NOW(), NOW())',
        [courseId, t.vol, t.name, t.sortOrder],
      );
      topicMap.push({ minOrder: t.minOrder, maxOrder: t.maxOrder, topicId: r.insertId, volId: t.vol });
    }
    console.log(`Created ${topicDefs.length} topics`);

    // ── Lessons ── (xóa quizzes cũ trước để tránh mồ côi khi lessons bị xóa)
    const oldLessons = await qr.query('SELECT id FROM lessons WHERE courseId = ?', [courseId]);
    for (const row of oldLessons) {
      await qr.query('DELETE FROM quizzes WHERE lessonId = ?', [row.id]);
    }
    await qr.query('DELETE FROM lessons WHERE courseId = ?', [courseId]);

    const lessonIdBySlug: Record<string, number> = {};
    for (const l of LESSONS) {
      const tm = topicMap.find((t) => l.sortOrder >= t.minOrder && l.sortOrder <= t.maxOrder);
      const volId = l.sortOrder <= 34 ? vol1Id : vol2Id;
      const r = await qr.query(
        `INSERT INTO lessons
         (courseId, volumeId, topicId, title, slug, content, lessonType, sortOrder, durationMinutes,
          isPreview, isPublished, createdAt, updatedAt)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
        [courseId, volId, tm?.topicId ?? null, l.title, l.slug, l.content, l.lessonType, l.sortOrder, l.durationMinutes, l.sortOrder <= 2 ? 1 : 0, 1],
      );
      lessonIdBySlug[l.slug] = r.insertId;
    }
    console.log(`Inserted ${LESSONS.length} lessons`);

    // ── Quizzes (batch đã soạn) ──
    let totalQ = 0;
    for (const [slug, questions] of Object.entries(QUIZZES)) {
      const lessonId = lessonIdBySlug[slug];
      if (!lessonId) { console.warn(`  (bỏ qua) không thấy lesson slug=${slug}`); continue; }
      const sortByEx: Record<number, number> = {};
      for (const q of questions) {
        sortByEx[q.ex] = (sortByEx[q.ex] ?? 0) + 1;
        await qr.query(
          `INSERT INTO quizzes
           (lessonId, exerciseNumber, questionType, questionText, optionsJson, correctAnswerJson,
            difficultyLevel, explanation, points, sortOrder, isActive, createdAt, updatedAt)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, NOW(), NOW())`,
          [
            lessonId, q.ex, q.type, q.text,
            q.opts != null ? JSON.stringify(q.opts) : null,
            JSON.stringify(q.ans),
            q.diff, q.expl ?? null, 10, sortByEx[q.ex],
          ],
        );
        totalQ += 1;
      }
      console.log(`  [${slug}] ${questions.length} câu hỏi`);
    }

    console.log(`\nDone! ${LESSONS.length} lessons, ${totalQ} câu hỏi (batch 1: Bài 1-8).`);
  } finally {
    await qr.release();
    await ds.destroy();
  }
}

seed().catch((err) => { console.error(err); process.exit(1); });
